// Valida token e parametros. O webhook fica exposto, entao nada daqui
// entra em SQL sem passar por Number() ou por lista fechada.

const q = $('Webhook Aprovacao').first().json.query || {};
const linha = $input.first().json || {};
const secretEsperado = String(linha.valor || '');

const id = Number(q.id);
const acao = String(q.acao || '').toLowerCase();
const token = String(q.token || '');

if (!secretEsperado) {
  return [{ json: { ok: false, http: 500, texto: 'APROVACAO_SECRET nao esta preenchido na tabela config.' } }];
}

// comparacao de tamanho fixo para nao vazar o segredo pelo tempo de resposta
function iguais(a, b) {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}

if (!iguais(token, secretEsperado)) {
  return [{ json: { ok: false, http: 403, texto: 'Token invalido.' } }];
}

if (!Number.isInteger(id) || id <= 0) {
  return [{ json: { ok: false, http: 400, texto: 'Parametro id invalido.' } }];
}

if (acao !== 'aprovar' && acao !== 'rejeitar') {
  return [{ json: { ok: false, http: 400, texto: "Parametro acao deve ser 'aprovar' ou 'rejeitar'." } }];
}

// Aprovar devolve a oferta para a fila com o orcamento de retry zerado:
// as tentativas gastas na previa nao contam para a publicacao de verdade.
const sql =
  acao === 'aprovar'
    ? 'UPDATE ofertas SET\n' +
      "  status = 'APROVADO',\n" +
      '  tentativas = 0,\n' +
      '  proxima_tentativa = NULL,\n' +
      '  motivo = NULL,\n' +
      '  lock_owner = NULL\n' +
      'WHERE id = ' +
      id +
      "\n  AND status = 'AGUARDANDO'"
    : 'UPDATE ofertas SET\n' +
      "  status = 'REJEITADO',\n" +
      "  motivo = 'Rejeitado manualmente na previa',\n" +
      '  proxima_tentativa = NULL,\n' +
      '  lock_owner = NULL\n' +
      'WHERE id = ' +
      id +
      "\n  AND status = 'AGUARDANDO'";

return [{ json: { ok: true, id, acao, sql } }];
